      "default": ""
    },
    "asnDatabase": {
      "type": "string",
      "title": "Organization database (blank: the one /orbit geodb gets)",
      "description": "Path of a MaxMind-format ASN database, which fills the org column. Blank uses the DB-IP ASN Lite file /orbit geodb downloads.",
      "default": ""
    },
    "proxy": {
      "type": "boolean",
      "title": "Start the proxy layer every session",
      "description": "true runs a local HTTPS proxy for the commands and MCP servers this session starts, so their hosts, bytes and latency reach the globe without decrypting anything; it sets HTTPS_PROXY for them. /orbit proxy on does this for one session.",
      "default": false
    },
    "fadeSeconds": {
      "type": "number",
      "title": "Seconds an arc stays on the globe",
      "description": "How long a finished connection's arc lingers before it fades. Higher is calmer, lower is busier.",
      "default": 25
    },
    "autoLog": {
      "type": "boolean",
      "title": "Write the trace to disk every session",
      "description": "true keeps this session's calls as JSONL in ~/.claude/orbit/traces, which is what /orbit replay reads. false writes nothing.",
      "default": true
    },
    "statusLine": {
      "type": "boolean",
      "title": "Show hosts and countries at the bottom of the terminal",
      "description": "The status line is the thin bar along the bottom of your terminal. true puts a count there, e.g. \"orbit · 6 hosts · 3 countries\". false leaves the bottom alone.",
      "default": false
    },
    "node": {
      "type": "string",
      "title": "Node.js to run the helpers (blank: node)",
      "description": "The node executable for the geo and proxy helpers, a name on PATH or a full path. Blank uses node from your PATH. The globe still draws without it; the city names and the proxy layer need it.",
      "default": ""
    }
  }
}
